import { useEffect, useReducer } from "react";
import { FetchActionType } from "./fetch.actionType";
import { fetchReducer } from "./fetch.reducer";
export const useFetch = (initialState, fetchPromise) => {
    const [state, dispatch] = useReducer(fetchReducer, Object.assign({ isLoading: false }, initialState));
    useEffect(() => {
        if (!fetchPromise) {
            return;
        }
        dispatch({ type: FetchActionType.Init, payload: undefined });
        fetchPromise.then(res => {
            dispatch({ type: FetchActionType.Success, payload: res });
        }).catch((e) => {
            dispatch({ type: FetchActionType.Fail, payload: e });
        });
    }, [fetchPromise, dispatch]);
    return state;
};
